var t = $input.first().json;
var chat = Number(t.chat_id), user = Number(t.user_id);
if (!isFinite(chat) || !isFinite(user)) { throw new Error('invalid ids'); }
var ex = String($execution.id).replace(/[^0-9a-zA-Z_-]/g, '');
return [{ json: { chat_id: chat, user_id: user, sql: "select public.nis_start_run('" + ex + "'," + chat + "," + user + ") as r" } }];

var qs = $('Build Search Queries').all();
var res = $input.all();
var out = []; var errors = 0;
for (var i = 0; i < res.length; i++) {
  var j = res[i].json; var intent = (qs[i] && qs[i].json.intent) || 'unknown';
  if (j.error || !j.web || !j.web.results) { errors++; continue; }
  j.web.results.forEach(function (r) { out.push({ url: r.url, title: r.title || '', description: r.description || '', extra: (r.extra_snippets || []).slice(0, 2), intent: intent, age: r.page_age || null }); });
}
return [{ json: { results: out, searches: res.length, search_errors: errors } }];

var d = $input.first().json;
var NL = String.fromCharCode(10);
function norm(u){ var m=/^https?:[/][/]([^/?#]+)([^?#]*)/i.exec(String(u||'')); if(!m) return null; var h=m[1].toLowerCase(); if(h.slice(-12)==='linkedin.com') h='www.linkedin.com'; var p=m[2].replace(/[/]+$/,''); return 'https://'+h+p; }
var BAD=['pinterest.','facebook.com','youtube.com','reddit.com','quora.com','twitter.com','x.com/','instagram.com','tiktok.com'];
var cap={person:24,post:10,career:10};
var seen={}; var cands=[]; var counts={person:0,post:0,career:0,skipped:0,dup:0,found:d.results.length};
d.results.forEach(function(r){
  var n=norm(r.url); if(!n){counts.skipped++;return;}
  if(seen[n]){counts.dup++;return;} seen[n]=1;
  var host=n.split('/')[2]; var path=n.slice(('https://'+host).length);
  var bad=false; BAD.forEach(function(b){ if((host+path).indexOf(b)>=0) bad=true; });
  if(bad){counts.skipped++;return;}
  var type=null;
  if(host==='www.linkedin.com'){
    if(path.indexOf('/in/')===0) type='person';
    else if(path.indexOf('/posts/')===0||path.indexOf('/pulse/')===0) type='post';
  } else if(r.intent==='career'){ type='career'; }
  if(!type){counts.skipped++;return;}
  if(counts[type]>=cap[type]){counts.skipped++;return;}
  counts[type]++;
  cands.push({id:'c'+(cands.length+1),type:type,url:n,title:String(r.title||'').slice(0,200),description:String(r.description||'').slice(0,600),extra:(r.extra||[]).join(' | ').slice(0,500),age:r.age||''});
});
var profile=[
 'CANDIDATE: Anupom Mojumder, AI Automation Engineer based in Sylhet, Bangladesh (looking for remote/international and Bangladesh roles).',
 'Verified skills: n8n, Make.com, Zapier, AI agents/agentic AI, Claude, Claude Code, OpenAI, Gemini, MCP, RAG, LangChain, ElevenLabs, Retell AI, Twilio, REST APIs, webhooks, Python, JavaScript, Supabase, PostgreSQL, CRM and lead-generation automation, AI customer support, business process automation.',
 'Positioning: builds practical AI-powered automation systems that solve real business problems.',
 'Never invent his experience, projects, employers, results or capabilities beyond the list above.'
].join(NL);
var rules=[
 'You analyse web-search results (titles/snippets only; you have NOT opened the pages). Use ONLY the supplied text. Never invent names, titles, companies, hiring status or post content. If something is not in the text, put it in unknown_facts or leave it empty.',
 'For each candidate return one object. kind must equal the candidate type (person, post, career).',
 'PERSON: name, position, company, category (career_opportunity|industry_leader|potential_client|professional_peer), score_breakdown {relevance 0-25 professional field relevance, career 0-25 career opportunity potential, ai_industry 0-20, business 0-15 business/collaboration potential, content 0-10, activity 0-5}, verified_facts[] (directly stated in the snippet), inferred_facts[], unknown_facts[], confidence (high|medium|low), reason (one concrete sentence), message (personalised LinkedIn connection note, English, max 280 characters, no fake familiarity, no flattery, no sales pitch, mention a specific shared topic from the snippet, first person as Anupom). Score honestly: limited snippet evidence means low activity/content scores. Irrelevant, spam or motivational accounts get low scores.',
 'POST: author_name, company, topic, main_argument (only what the snippet shows), relevance 0-100, networking_value, suggested_comment and alternative_comment (natural, insightful, professional, 1-3 sentences, no generic praise, no invented personal experience, no self-promotion; base only on the snippet), because only the snippet is available.',
 'CAREER (job or hiring page): title, company, remote_policy (remote|hybrid|onsite|unknown), bangladesh_eligibility (verified_accepts|verified_excludes|unknown), eligibility_evidence (an EXACT verbatim quote from the supplied text proving it; otherwise empty and eligibility unknown), is_bangladesh_based (true only if the text says Bangladesh/Dhaka etc.), location_text, relevance 0-100 for an AI automation engineer. Never assume global remote means Bangladesh is accepted.',
 'Output ONLY valid JSON: {"results":[{"id":"c1","kind":"person",...}]}. Include every candidate id exactly once. Candidates with no relevance still appear with low scores.'
].join(NL);
var batches=[]; var size=8;
for(var i=0;i<cands.length;i+=size){
  var chunk=cands.slice(i,i+size); var map={};
  var lines=chunk.map(function(c){ map[c.id]=c; return ['ID: '+c.id,'TYPE: '+c.type,'URL: '+c.url,'TITLE: '+c.title,'SNIPPET: '+c.description,'EXTRA: '+c.extra,'AGE: '+c.age].join(NL); }).join(NL+'---'+NL);
  batches.push({json:{prompt:profile+NL+NL+rules+NL+NL+'CANDIDATES:'+NL+lines,cands:map,stats:counts,searches:d.searches,search_errors:d.search_errors}});
}
if(!batches.length){ batches.push({json:{prompt:'Reply with exactly: {"results":[]}',cands:{},stats:counts,searches:d.searches,search_errors:d.search_errors}}); }
return batches;

var batches=$('Normalize and Batch').all();
var cmap={};
batches.forEach(function(b){ var c=b.json.cands||{}; Object.keys(c).forEach(function(k){ cmap[k]=c[k]; }); });
var report_id=$('DB Start Run').first().json.r.report_id;
var meta={kind:'meta',sql:'select 1 as r',batches_total:batches.length,batches_parsed:0,providers:[]};
var out=[meta];
function txt(j){
  if(Array.isArray(j.content)){ for(var q=0;q<j.content.length;q++){ if(j.content[q].type==='text'&&j.content[q].text) return {t:j.content[q].text,p:'claude'}; } }
  if(j.output){ for(var i=0;i<j.output.length;i++){ var o=j.output[i]; if(o.content){ for(var k=0;k<o.content.length;k++){ if(o.content[k].text) return {t:o.content[k].text,p:'openai'}; } } } }
  return null;
}
function parse(t){ var a=t.indexOf('{'),b=t.lastIndexOf('}'); if(a<0||b<=a) return null; try{ return JSON.parse(t.slice(a,b+1)); }catch(e){ return null; } }
function b64(o){ return Buffer.from(JSON.stringify(o),'utf8').toString('base64'); }
function clamp(v,m){ v=Number(v); if(!isFinite(v)) v=0; return Math.max(0,Math.min(m,Math.round(v))); }
function str(v,n){ return (v==null?'':String(v)).slice(0,n); }
function arr(v,n,m){ return (Array.isArray(v)?v:[]).slice(0,n).map(function(s){ return str(s,m); }); }
var dec="convert_from(decode('";
var seenIds={};
$input.all().forEach(function(it){
  var x=txt(it.json); if(!x) return;
  var p=parse(x.t); if(!p||!Array.isArray(p.results)) return;
  meta.batches_parsed++; if(meta.providers.indexOf(x.p)<0) meta.providers.push(x.p);
  p.results.forEach(function(r){
    var c=cmap[r.id]; if(!c||seenIds[r.id]) return; seenIds[r.id]=1;
    if(r.kind!==c.type) return;
    if(c.type==='person'){
      var bd=r.score_breakdown||{};
      var b={relevance:clamp(bd.relevance,25),career:clamp(bd.career,25),ai_industry:clamp(bd.ai_industry,20),business:clamp(bd.business,15),content:clamp(bd.content,10),activity:clamp(bd.activity,5)};
      var score=b.relevance+b.career+b.ai_industry+b.business+b.content+b.activity;
      var name=str(r.name,120).trim(); if(!name) return;
      var hay0=(c.title+' '+c.description+' '+c.extra).toLowerCase(); var tok=name.toLowerCase().split(' ')[0];
      if(tok.length<2||hay0.indexOf(tok)<0||name.toLowerCase().indexOf('anupom')>=0) return;
      var cat=['career_opportunity','industry_leader','potential_client','professional_peer'].indexOf(r.category)>=0?r.category:'unclassified';
      var msg=str(r.message,290); var vf=arr(r.verified_facts,6,240); var inf=arr(r.inferred_facts,6,240);
      var person={profile_url:c.url,name:name,position:str(r.position,160),company:str(r.company,160),category:cat,skills:[],verified_facts:{statements:vf},inferred_facts:{statements:inf},unknown_facts:arr(r.unknown_facts,6,200),evidence_urls:[c.url],confidence:['high','medium','low'].indexOf(r.confidence)>=0?r.confidence:'low',relevance_score:score,score_breakdown:b};
      var payload={person:person,report_id:report_id,score:score,reason:str(r.reason,400),evidence_url:c.url,message:msg};
      var sql="with p as (select "+dec+b64(payload)+"','base64'),'UTF8')::jsonb j), u as (select public.nis_upsert_person(p.j->'person') r, p.j j from p) select u.r, case when (u.r->>'eligible')::boolean then public.nis_record_recommendation((u.r->>'id')::uuid,(u.j->>'report_id')::uuid,(u.j->>'score')::int,u.j->>'reason',u.j->>'evidence_url',u.j->>'message') end as rec from u";
      out.push({kind:'person',sql:sql,display:{name:name,position:person.position,company:person.company,score:score,category:cat,confidence:person.confidence,reason:payload.reason,url:c.url,message:msg,verified:vf,inferred:inf}});
    } else if(c.type==='post'){
      var basis=(c.description||'').length>=40?'snippet':'none';
      var post={post_url:c.url,author_name:str(r.author_name,120),company:str(r.company,160),topic:str(r.topic,200),main_argument:str(r.main_argument,500),discussion_points:[],content_basis:basis,networking_value:str(r.networking_value,300),relevance_score:clamp(r.relevance,100),suggested_comment:str(r.suggested_comment,600),alternative_comment:str(r.alternative_comment,600),evidence_urls:[c.url]};
      var pp={post:post,score:post.relevance_score};
      var sql2="with p as (select "+dec+b64(pp)+"','base64'),'UTF8')::jsonb j), u as (select public.nis_upsert_post(p.j->'post') r, p.j j from p) select u.r, case when (u.r->>'eligible')::boolean and (u.j->>'score')::int>=70 then public.nis_mark_post_recommended((u.r->>'id')::uuid) end as mk from u";
      out.push({kind:'post',sql:sql2,display:{author:post.author_name,company:post.company,topic:post.topic,score:post.relevance_score,url:c.url,comment:post.suggested_comment,alt:post.alternative_comment,basis:basis,value:post.networking_value}});
    } else if(c.type==='career'){
      var rel=clamp(r.relevance,100); if(rel<60) return;
      var ev=str(r.eligibility_evidence,300).trim(); var hay=(c.title+' '+c.description+' '+c.extra).toLowerCase();
      var el=r.bangladesh_eligibility;
      if(el==='verified_accepts'||el==='verified_excludes'){ if(!ev||hay.indexOf(ev.toLowerCase())<0){ el='unknown'; ev=''; } } else { el='unknown'; ev=''; }
      var bdb=r.is_bangladesh_based===true&&/bangladesh|dhaka|chittagong|sylhet/.test(hay);
      var job={job_url:c.url,title:str(r.title,200),company:str(r.company,160),remote_policy:r.remote_policy,bangladesh_eligibility:el,eligibility_evidence:ev,location_text:str(r.location_text,160),is_bangladesh_based:bdb,relevance_score:rel};
      out.push({kind:'career',sql:"select public.nis_upsert_career("+dec+b64(job)+"','base64'),'UTF8')::jsonb) as r",display:{title:job.title,company:job.company,url:c.url,eligibility:el,evidence:ev,remote:job.remote_policy,bd:bdb,score:rel}});
    }
  });
});
return out.map(function(o){ return {json:o}; });

var NL=String.fromCharCode(10);
var chat=$('Prep Start Run').first().json.chat_id;
var start=$('DB Start Run').first().json.r;
var parsed=$('Parse Analysis').all();
var persisted=$('DB Persist').all();
var sf=$('DB Stop Check Final').first().json;
var stopped=!!(sf.r&&sf.r.stop);
var nb=$('Normalize and Batch').first().json; var st=nb.stats||{};
var meta=parsed[0].json;
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function tier(s){ return s>=85?'Highly Valuable':(s>=70?'Strong Match':(s>=55?'Moderate':'Not Recommended')); }
function cut(s){ return s.length>3900?s.slice(0,3890)+'...':s; }
var people=[],posts=[],careers=[];
var uniq=0,newp=0,dup=0,notRec=0,fail=0,postsDisc=0,postsNew=0,comments=0;
for(var i=1;i<parsed.length;i++){
  var p=parsed[i].json; var res=(persisted[i]&&persisted[i].json)||{};
  if(res.error||!res.r||res.r.ok!==true){ fail++; continue; }
  var r=res.r; var d=p.display;
  if(p.kind==='person'){
    uniq++; if(r.is_new) newp++; else dup++;
    if(res.rec&&res.rec.ok===true) people.push({id:r.id,d:d}); else notRec++;
  } else if(p.kind==='post'){
    postsDisc++; if(r.is_new) postsNew++;
    if(res.mk&&res.mk.ok===true){ posts.push({id:r.id,d:d}); if(d.comment) comments++; }
  } else if(p.kind==='career'){ careers.push({id:r.id,d:d}); }
}
people.sort(function(a,b){ return b.d.score-a.d.score; });
var status=stopped?'stopped':((meta.batches_parsed<meta.batches_total||(nb.search_errors||0)>0)?'partial':'completed');
var vAcc=careers.filter(function(c){ return c.d.eligibility==='verified_accepts'||c.d.bd; });
var unv=careers.filter(function(c){ return !(c.d.eligibility==='verified_accepts'||c.d.bd); });
var clients=people.filter(function(x){ return x.d.category==='potential_client'; }).length;
var sum=[
 '📊 <b>Research report</b> ('+status+')',
 'Execution: <code>'+esc(start.execution_id)+'</code> · '+new Date().toISOString().slice(0,10),
 'Sources: Brave Search API ('+(nb.searches||0)+' queries, '+(nb.search_errors||0)+' failed). Apify: not used this run (needs API token). Search results are leads, not verified facts.',
 'AI: '+(meta.providers.length?meta.providers.join(' + '):'none available')+' ('+meta.batches_parsed+'/'+meta.batches_total+' batches analysed)',
 'Search hits: '+(st.found||0)+' · duplicates removed: '+(st.dup||0)+' · analysed: '+((st.person||0)+(st.post||0)+(st.career||0)),
 'Profiles: '+uniq+' unique ('+newp+' new, '+dup+' already known) · recommended (score 70+): '+people.length+' · potential clients: '+clients,
 'Posts: '+postsDisc+' analysed · recommended: '+posts.length+' · comments generated: '+comments,
 'Career pages: '+careers.length+' ('+vAcc.length+' Bangladesh-eligible/based, '+unv.length+' eligibility unverified)',
 (fail?'⚠️ '+fail+' items failed to save.':''),
 (people.length+posts.length===0?'No recommendation met the 70+ threshold with sufficient evidence. Nothing was padded.':'')
].filter(function(x){ return x; }).join(NL);
var out=[{kind:'plain',chat_id:chat,text:cut(sum)}];
people.forEach(function(x){ var d=x.d;
  var t=['👤 <b>'+esc(d.name)+'</b>',esc(d.position)+(d.company?' @ '+esc(d.company):''),'Score <b>'+d.score+'</b> ('+tier(d.score)+') · '+esc(d.category)+' · confidence '+esc(d.confidence),'Why: '+esc(d.reason),'Evidence: '+esc(d.url),'','VERIFIED (snippet): '+(d.verified.length?esc(d.verified.join('; ')):'none'),'INFERRED: '+(d.inferred.length?esc(d.inferred.join('; ')):'none'),'','✉️ Suggested message (tap to copy):','<code>'+esc(d.message)+'</code>'].join(NL);
  out.push({kind:'person',chat_id:chat,id:x.id,url:d.url,text:cut(t)}); });
posts.forEach(function(x){ var d=x.d;
  var t=['📝 <b>'+esc(d.author||'Unknown author')+'</b>'+(d.company?' · '+esc(d.company):''),'Topic: '+esc(d.topic),'Relevance '+d.score+' · '+esc(d.value),(d.basis==='snippet'?'⚠️ Based on a search snippet only. Read the full post before commenting.':''),'','💬 Suggested comment (tap to copy):','<code>'+esc(d.comment)+'</code>',(d.alt?'Alternative:'+NL+'<code>'+esc(d.alt)+'</code>':''),'Source: '+esc(d.url)].join(NL);
  out.push({kind:'post',chat_id:chat,id:x.id,url:d.url,text:cut(t)}); });
if(careers.length){
  var ct=['💼 <b>Career opportunities</b>','Verified/Bangladesh-based:'];
  if(!vAcc.length) ct.push('none');
  vAcc.forEach(function(c){ ct.push('• '+esc(c.d.title)+' @ '+esc(c.d.company)+' — '+esc(c.d.evidence||'Bangladesh-based')+' '+esc(c.d.url)); });
  ct.push(NL+'Eligibility UNVERIFIED (check Bangladesh acceptance before applying):');
  unv.slice(0,8).forEach(function(c){ ct.push('• '+esc(c.d.title)+' @ '+esc(c.d.company)+' ('+esc(c.d.remote)+') '+esc(c.d.url)); });
  out.push({kind:'plain',chat_id:chat,text:cut(ct.join(NL))});
}
var summary={status:status,searches:nb.searches||0,search_errors:nb.search_errors||0,found:st.found||0,analysed:(st.person||0)+(st.post||0)+(st.career||0),unique_profiles:uniq,new_profiles:newp,known_profiles:dup,recommended_people:people.length,posts_analysed:postsDisc,recommended_posts:posts.length,comments:comments,career_pages:careers.length,providers:meta.providers,save_failures:fail,apify_used:false};
var b64=function(o){ return Buffer.from(typeof o==='string'?o:JSON.stringify(o),'utf8').toString('base64'); };
var rid=String(start.report_id).replace(/[^0-9a-f-]/g,'');
var ex=String(start.execution_id).replace(/[^0-9a-zA-Z_-]/g,'');
out[0].finish_sql="select public.nis_finish_run('"+rid+"'::uuid,'"+status+"',convert_from(decode('"+b64(summary)+"','base64'),'UTF8')::jsonb,convert_from(decode('"+b64(sum)+"','base64'),'UTF8')) as r, public.nis_log('"+ex+"','NIS 02 Research Orchestrator','Finish','info','run finished: "+status+"',convert_from(decode('"+b64(summary)+"','base64'),'UTF8')::jsonb)";
return out.map(function(o){ return {json:o}; });
